#include <SPI.h>
#include <Ethernet.h>
#include <EthernetPing.h>
#include <Wire.h>
#include <GyverOLED.h>

// Конфигурация пинов
const int ETH_CS_PIN  = 5;
const int ETH_RST_PIN = 26;
const int BUTTON_PIN  = 34; 

const int LED_GREEN   = 12; 
const int LED_RED     = 13; 
const int BUZZER_PIN  = 17; 

// Пины для проверки жил витой пары (8 штук)
const int cablePins[8] = {2, 4, 15, 27, 14, 32, 33, 25};

GyverOLED<SSH1106_128x64> oled;

byte mac[] = { 0xDE, 0xAD, 0xBE, 0xEF, 0xFE, 0xED };
IPAddress pingTarget(8, 8, 8, 8); 
EthernetPing ping;
EthernetClient client; 

// Настройки сканера портов
const int portsToScan[] = {21, 22, 23, 80, 443, 445, 3389};
const char* portNames[] = {"FTP", "SSH", "Tel", "HTTP", "HTTPS", "SMB", "RDP"};
const int totalPorts = 7;

enum DeviceMode {
  MODE_TESTER,       
  MODE_PORT_BLINK,   
  MODE_PORT_SCAN,    
  MODE_IP_SCAN,
  MODE_CABLE_TEST   
};
DeviceMode currentMode = MODE_TESTER;

bool lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;

unsigned long lastBlinkToggleTime = 0;
bool blinkState = false;
bool scanExecuted = false;   
bool ipScanExecuted = false; 

void resetEthernetHardware() {
  pinMode(ETH_RST_PIN, OUTPUT);
  digitalWrite(ETH_RST_PIN, LOW); delay(50);
  digitalWrite(ETH_RST_PIN, HIGH); delay(200);
}

void beep(int frequency, int duration) {
  tone(BUZZER_PIN, frequency, duration);
  delay(duration);
  noTone(BUZZER_PIN);
}

void playSuccessSound() {
  tone(BUZZER_PIN, 1500, 80);  delay(90);
  tone(BUZZER_PIN, 2000, 120); delay(130);
  noTone(BUZZER_PIN);
}

void playErrorSound() {
  tone(BUZZER_PIN, 600, 200);  delay(220);
  tone(BUZZER_PIN, 400, 300);  delay(320);
  noTone(BUZZER_PIN);
}

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  pinMode(LED_GREEN, OUTPUT);
  pinMode(LED_RED, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  digitalWrite(LED_GREEN, HIGH);     digitalWrite(LED_RED, HIGH);
  beep(1000, 100); delay(100);       beep(1500, 100);
  digitalWrite(LED_GREEN, LOW);      digitalWrite(LED_RED, LOW);

  oled.init(); oled.clear(); oled.update();

  resetEthernetHardware();
  Ethernet.init(ETH_CS_PIN);
}

void checkButton() {
  int reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonState) { lastDebounceTime = millis(); }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading == LOW && lastButtonState == HIGH) {
      beep(1200, 40);
      digitalWrite(LED_GREEN, LOW); digitalWrite(LED_RED, LOW);

      if (currentMode == MODE_TESTER) {
        currentMode = MODE_PORT_BLINK;
      } else if (currentMode == MODE_PORT_BLINK) {
        currentMode = MODE_PORT_SCAN; scanExecuted = false; 
        resetEthernetHardware(); Ethernet.begin(mac, 2000, 2000); 
      } else if (currentMode == MODE_PORT_SCAN) {
        currentMode = MODE_IP_SCAN; ipScanExecuted = false;
        resetEthernetHardware(); Ethernet.begin(mac, 2000, 2000);
      } else if (currentMode == MODE_IP_SCAN) {
        currentMode = MODE_CABLE_TEST;
        digitalWrite(ETH_RST_PIN, LOW); 
      } else {
        currentMode = MODE_TESTER; resetEthernetHardware(); 
      }

      oled.clear(); oled.setCursor(0, 2); oled.setScale(2);
      oled.println(" CHANGING "); oled.println("  MODE... "); oled.update(); oled.setScale(1);
      delay(500); 
    }
  }
  lastButtonState = reading;
}

void runTesterLogic() {
  digitalWrite(LED_GREEN, LOW); digitalWrite(LED_RED, LOW);
  oled.clear(); oled.setCursor(0, 0);
  oled.println("=== LAN TESTER ==="); oled.println("DHCP Connecting..."); oled.update();

  if (Ethernet.begin(mac) == 0) {
    digitalWrite(LED_RED, HIGH); playErrorSound();
    oled.clear(); oled.setCursor(0, 0); oled.println("=== DHCP ERROR ===");
    if (Ethernet.hardwareStatus() == EthernetNoHardware) oled.println("\nW5500 not found!");
    else if (Ethernet.linkStatus() == LinkOFF) oled.println("\nNo Cable Connected!");
    else oled.println("\nDHCP Failed!");
    oled.update();
    unsigned long waitStart = millis();
    while (millis() - waitStart < 3000) { checkButton(); if (currentMode != MODE_TESTER) return; }
    return; 
  }

  digitalWrite(LED_GREEN, HIGH); playSuccessSound();
  oled.clear(); oled.setCursor(0, 0);
  oled.println("=== NET READY ===");
  oled.print("IP:  "); oled.println(Ethernet.localIP());
  oled.print("GW:  "); oled.println(Ethernet.gatewayIP());
  oled.println("--------------------"); oled.print("Ping 8.8.8.8... "); oled.update();

  int result = ping.ping(pingTarget, 3);
  oled.setCursor(0, 5);
  if (result > 0) {
    digitalWrite(LED_GREEN, HIGH); digitalWrite(LED_RED, LOW);
    oled.print("SUCCESS! "); oled.print(result); oled.println(" ms");
  } else {
    digitalWrite(LED_GREEN, LOW);  digitalWrite(LED_RED, HIGH); 
    oled.println("FAILED! (Timeout)"); playErrorSound();
  }
  oled.update();
  unsigned long loopStart = millis();
  while (millis() - loopStart < 4000) { checkButton(); if (currentMode != MODE_TESTER) return; }
}

void runBlinkerLogic() {
  if (millis() - lastBlinkToggleTime >= 1500) {
    lastBlinkToggleTime = millis();
    blinkState = !blinkState;
    if (blinkState) {
      digitalWrite(ETH_RST_PIN, HIGH); delay(50);
      Ethernet.init(ETH_CS_PIN); Ethernet.begin(mac, 200, 200); 
      digitalWrite(LED_GREEN, HIGH); digitalWrite(LED_RED, LOW); beep(1800, 50);
      oled.clear(); oled.setCursor(0, 0);
      oled.println("=== PORT BLINKER ==="); oled.println("\n    [ LINK ON ]"); oled.update();
    } else {
      digitalWrite(ETH_RST_PIN, LOW); 
      digitalWrite(LED_GREEN, LOW); digitalWrite(LED_RED, HIGH); beep(1000, 50);
      oled.clear(); oled.setCursor(0, 0);
      oled.println("=== PORT BLINKER ==="); oled.println("\n    [ LINK OFF ]"); oled.update();
    }
  }
}

void runPortScanLogic() {
  if (scanExecuted) return; 
  IPAddress targetIP = Ethernet.gatewayIP();
  oled.clear(); oled.setCursor(0, 0);
  oled.println("=== PORT SCANNER ==="); oled.print("Target IP: "); oled.println(targetIP); oled.update();
  if (targetIP == IPAddress(0,0,0,0)) {
    digitalWrite(LED_RED, HIGH); playErrorSound(); scanExecuted = true; return;
  }
  int currentLine = 3; bool foundAny = false;
  for (int i = 0; i < totalPorts; i++) {
    checkButton(); if (currentMode != MODE_PORT_SCAN) return;
    int port = portsToScan[i];
    if (client.connect(targetIP, port)) {
      foundAny = true; digitalWrite(LED_GREEN, HIGH); beep(2200, 60); 
      oled.setCursor(0, currentLine);
      oled.print("-> "); oled.print(port); oled.print(" ("); oled.print(portNames[i]); oled.println(") OPEN"); oled.update();
      client.stop(); currentLine++;
    }
    digitalWrite(LED_GREEN, LOW);   if (currentLine > 7) break; 
  }
  if (!foundAny) {
    digitalWrite(LED_RED, HIGH);
    oled.setCursor(0, 4); oled.println("All standard ports\nare CLOSED."); oled.update();
  } else {
    digitalWrite(LED_GREEN, HIGH); 
  }
  scanExecuted = true;
}

void runIpScanLogic() {
  if (ipScanExecuted) return;
  IPAddress myIP = Ethernet.localIP();
  oled.clear(); oled.setCursor(0, 0);
  oled.println("=== NET IP SCAN ==="); oled.update();
  if (myIP == IPAddress(0,0,0,0)) {
    digitalWrite(LED_RED, HIGH); playErrorSound(); ipScanExecuted = true; return;
  }

  int devicesFound = 0; int currentLine = 2;
  oled.setCursor(0, 1);
  oled.print("Subnet: "); oled.print(myIP[0]); oled.print("."); oled.print(myIP[1]); oled.print("."); oled.print(myIP[2]); oled.println(".X"); oled.update();

  for (int host = 1; host <= 25; host++) {
    checkButton(); if (currentMode != MODE_IP_SCAN) return;

    // Исправлено создание адреса под жесткие требования Arduino CLI
    IPAddress scanIP(myIP[0], myIP[1], myIP[2], host); 

    oled.setCursor(110, 0); oled.print(host); oled.print(" "); oled.update();
    int replyTime = ping.ping(scanIP, 1); 
    if (replyTime > 0) {
      devicesFound++; digitalWrite(LED_GREEN, HIGH); beep(2000, 30); digitalWrite(LED_GREEN, LOW);
      if (currentLine <= 6) {
        oled.setCursor(0, currentLine); oled.print("-> ."); oled.print(host);
        if (scanIP == Ethernet.gatewayIP()) oled.print(" (Router)");
        else if (scanIP == myIP) oled.print(" (Tester)");
        oled.println(" ONLINE"); oled.update(); currentLine++;
      }
    }
  }
  oled.setCursor(0, 7); oled.print("Total found: "); oled.print(devicesFound); oled.print(" dev"); oled.update();
  if (devicesFound > 0) digitalWrite(LED_GREEN, HIGH); else digitalWrite(LED_RED, HIGH);
  ipScanExecuted = true;
}

void runCableTestLogic() {
  oled.clear(); oled.setCursor(0, 0);
  oled.println("=== CABLE TESTER ===");
  oled.println("Pins 12345678");
  oled.print("Stat: ");

  for (int i = 0; i < 8; i++) {
    pinMode(cablePins[i], OUTPUT);
    digitalWrite(cablePins[i], HIGH);
    oled.print("P");
    delay(50);
    digitalWrite(cablePins[i], LOW);
    pinMode(cablePins[i], INPUT);
  }

  oled.println("\n\nLoop testing...");
  oled.update();
  delay(1000);
}

void loop() {
  checkButton();

  switch (currentMode) {
    case MODE_TESTER:      runTesterLogic();    break;
    case MODE_PORT_BLINK:  runBlinkerLogic();   break;
    case MODE_PORT_SCAN:   runPortScanLogic();  break;
    case MODE_IP_SCAN:     runIpScanLogic();    break;
    case MODE_CABLE_TEST:  runCableTestLogic(); break;
  }
}
